// Original procedural soundtrack and movement sounds, generated locally with Web Audio.
export class GameAudio{
 constructor(){this.context=null;this.musicBus=null;this.effectBus=null;this.timer=null;this.beat=0;this.volume=.6;this.music=.25}
 unlock(){if(!this.context){const C=globalThis.AudioContext||globalThis.webkitAudioContext;if(!C)return;this.context=new C();this.effectBus=this.context.createGain();this.musicBus=this.context.createGain();this.effectBus.connect(this.context.destination);this.musicBus.connect(this.context.destination);this.setLevels(this.volume*100,this.music*100);this.timer=setInterval(()=>this.tick(),160);this.tick()}if(this.context.state==='suspended')this.context.resume().catch(()=>{})}
 setLevels(effects,music){this.volume=effects/100;this.music=music/100;if(this.effectBus)this.effectBus.gain.setTargetAtTime(this.volume,this.context.currentTime,.04);if(this.musicBus)this.musicBus.gain.setTargetAtTime(this.music*.28,this.context.currentTime,.1)}
 tone(frequency,duration,gain,bus,type='sine',delay=0){const c=this.context;if(!c)return;const at=c.currentTime+delay,o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.setValueAtTime(frequency,at);g.gain.setValueAtTime(.0001,at);g.gain.exponentialRampToValueAtTime(Math.max(.0002,gain),at+.012);g.gain.exponentialRampToValueAtTime(.0001,at+duration);o.connect(g);g.connect(bus);o.start(at);o.stop(at+duration+.02);o.onended=()=>{o.disconnect();g.disconnect()}}
 noise(duration,gain,cutoff){const c=this.context;if(!c)return;const b=c.createBuffer(1,Math.ceil(c.sampleRate*duration),c.sampleRate),data=b.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*(1-i/data.length);const s=c.createBufferSource(),g=c.createGain(),filter=c.createBiquadFilter();filter.type='lowpass';filter.frequency.value=cutoff;s.buffer=b;g.gain.value=gain;s.connect(filter);filter.connect(g);g.connect(this.effectBus);s.start();s.onended=()=>{s.disconnect();filter.disconnect();g.disconnect()}}
 play(kind,w={}){if(!this.context||this.context.state!=='running')return;const bus=this.effectBus;
  if(['step','run','land','slide'].includes(kind)){const run=kind==='run';this.noise(kind==='slide'?.65:kind==='land'?.19:.12,kind==='slide'?.3:kind==='land'?.28:run?.24:.16,kind==='slide'?1800:run?1000:750);this.tone(kind==='slide'?140:run?115:95,.12,run?.14:.09,bus);return}
  if(kind==='shot'){this.noise(w.mechanic==='melee'?.16:.13,w.mechanic==='melee'?.16:.3,w.cat==='sr'?900:2500);this.tone(w.mechanic==='arrow'?520:w.mechanic==='melee'?350:w.mechanic==='rocket'?48:95,.16,.13,bus,w.mechanic?'sine':'sawtooth');return}
  this.tone(({hit:680,kill:920,jump:240,reload:380,hurt:130,select:540})[kind]||440,.14,.08,bus);
 }
 tick(){const c=this.context;if(!c||c.state!=='running')return;const n=this.beat++,notes=[110,130.81,98,146.83],root=notes[Math.floor(n/32)%4];if(n%4===0)this.tone(root,.5,.2,this.musicBus,'triangle');if(n%2===0)this.tone(root*([2,3,2.5,4][Math.floor(n/2)%4]),.22,.09,this.musicBus,'sine');if(n%4===0)this.tone(55,.12,.32,this.musicBus);if(n%8===4)this.tone(180,.08,.06,this.musicBus,'triangle')}
}
